  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "This systematic review and meta-analysis evaluates the effectiveness of AI-driven tools, particularly conversational agents (CAs), in alleviating psychological distress and improving mental health outcomes. The focus is on their impact across diverse populations, including clinical, subclinical, and older adults.",
